import { z } from "zod";

const MAX_UPLOAD_BYTES = 5 * 1024 * 1024 * 1024;
const MAX_PATH_LENGTH = 1024;

const pathSegment = z
  .string()
  .min(1)
  .max(255)
  .refine((s) => s !== "." && s !== "..", "relative segments are not allowed")
  .refine((s) => !/[\u0000-\u001f\\]/.test(s), "control characters and backslashes are not allowed");

export const filePath = z
  .string()
  .max(MAX_PATH_LENGTH)
  .transform((p) => p.normalize("NFC"))
  .refine((p) => p.startsWith("/"), "path must be absolute within the drive")
  .refine((p) => !p.endsWith("/") , "path must name a file")
  .refine(
    (p) => p.slice(1).split("/").every((seg) => pathSegment.safeParse(seg).success),
    "path contains an invalid segment",
  );

export const startUploadSchema = z
  .object({
    path: filePath,
    sizeBytes: z.number().int().nonnegative().max(MAX_UPLOAD_BYTES),
    sha256: z.string().regex(/^[a-f0-9]{64}$/, "sha256 must be 64 lowercase hex characters"),
    baseRevision: z.number().int().nonnegative().nullable(),
    modifiedAt: z.string().datetime({ offset: true }),
    conflictPolicy: z.enum(["fail", "keep_both", "overwrite"]).default("fail"),
  })
  .strict();

export type StartUploadRequest = z.infer<typeof startUploadSchema>;

import type { Request, Response } from "express";
import { startUploadSchema, type StartUploadRequest } from "./uploadSchema";

export interface SyncStore {
  currentRevision(driveId: string, path: string): Promise<number | null>;
  createUploadSession(driveId: string, req: StartUploadRequest): Promise<{ uploadId: string; uploadUrl: string }>;
}

export function startUploadHandler(store: SyncStore) {
  return async (req: Request, res: Response) => {
    const driveId = req.params.driveId;
    const parsed = startUploadSchema.safeParse(req.body);
    if (!parsed.success) {
      res.status(400).json({
        error: "invalid_request",
        details: parsed.error.issues.map((i) => ({ field: i.path.join("."), message: i.message })),
      });
      return;
    }
    const body = parsed.data;

    const current = await store.currentRevision(driveId, body.path);
    if (body.baseRevision !== current && body.conflictPolicy === "fail") {
      res.status(409).json({ error: "revision_conflict", currentRevision: current });
      return;
    }

    const session = await store.createUploadSession(driveId, body);
    res.status(201).json(session);
  };
}
